#!/usr/bin/env bash
# Tests for pm-dashboard-backup.sh's dataset staging copies (#1023):
#   the copies that stage the aggregator files, the snapshots tree, the
#   meta-quota-export files, and the db-dumps dir were unchecked, and the
#   manifest is generated by walking the staged tree — so a failed copy
#   (a present but unreadable dataset file) was invisible to the verify
#   step: the run reported full success with an incomplete archive,
#   uploaded it to both remotes, and advanced the journal cursor.
# This drives the REAL script (no pasted copy) with stubbed tools:
# a scratch HOME, a stub bws printing fake credential names/values, a
# stub journalctl, and a stub rclone backed by a local store directory.
# Scenarios:
#   * unreadable aggregator file  — exit non-zero, FAILED line names the
#     file, nothing uploaded, marker unchanged
#   * unreadable snapshots file   — same, naming the snapshots tree
#   * unreadable meta-export file — same, naming the file
#   * unreadable db-dumps file    — same, naming the dumps dir
#   * missing files (control)     — WARN as before, exit 0, archive
#     uploaded, marker advances: absent is not unreadable
set -uo pipefail

SELF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
if [[ -f "$SELF_DIR/pm-dashboard-backup.sh" ]]; then
  SCRIPT="$SELF_DIR/pm-dashboard-backup.sh"
else
  SCRIPT="$SELF_DIR/modules/pm-dashboard-backup.sh"
fi

TMP_ROOT="$(mktemp -d)"
trap 'chmod -R u+rwX "$TMP_ROOT" 2>/dev/null; rm -rf "$TMP_ROOT"' EXIT

failures=0
fail() {
  echo "FAIL: $1" >&2
  failures=$((failures + 1))
}

BIN="$TMP_ROOT/bin"
mkdir -p "$BIN"

{ printf '#!%s\n' "$BASH"; cat <<'STUB'
if [[ "${1:-} ${2:-}" == "secret list" ]]; then
  printf '%s\n' '[{"key":"cloudflare.r2-backups-access-key-id","value":"fake-access-key-id"},{"key":"cloudflare.r2-backups-secret-access-key","value":"fake-secret-access-key"},{"key":"cloudflare.r2-endpoint","value":"https://example.invalid"}]'
  exit 0
fi
echo "stub bws: unsupported args: $*" >&2
exit 1
STUB
} >"$BIN/bws"

{ printf '#!%s\n' "$BASH"; cat <<'STUB'
echo "stub journal line"
exit 0
STUB
} >"$BIN/journalctl"

{ printf '#!%s\n' "$BASH"; cat <<'STUB'
store="${RCLONE_STUB_DIR:?RCLONE_STUB_DIR unset}"
mkdir -p "$store"
key() { printf '%s' "$1" | tr '/:' '__'; }
cmd="${1:-}"
shift || true
case "$cmd" in
  copyto) cp "$1" "$store/$(key "$2")" ;;
  cat)
    f="$store/$(key "$1")"
    [[ -f "$f" ]] || exit 1
    cat "$f"
    ;;
  lsf) exit 0 ;;
  purge) exit 0 ;;
  *)
    echo "stub rclone: unsupported command: $cmd" >&2
    exit 1
    ;;
esac
STUB
} >"$BIN/rclone"
chmod +x "$BIN/bws" "$BIN/journalctl" "$BIN/rclone"

PRESET=1000000000
DATE_ARG=2026-10-28
RC=0
HOME_DIR=""
STORE_DIR=""

# Build a complete dataset under a fresh scratch HOME, then break one
# member per scenario with $1 (a path relative to the HOME, chmod 000).
setup_and_run() {
  local name="$1" break_rel="${2:-}"
  HOME_DIR="$TMP_ROOT/$name/home"
  STORE_DIR="$TMP_ROOT/$name/rclone-store"
  local agg="$HOME_DIR/.local/state/pm-aggregator"
  local meta="$HOME_DIR/atlas/meta-quota-export"
  mkdir -p "$HOME_DIR/backups/dashboard" "$agg/snapshots" "$meta" \
    "$HOME_DIR/backups/db-dumps/$DATE_ARG"
  local f
  for f in actions.json comments.json fleet-feed.json quota-current.json \
           registry.json quota-gatherer-state.json quota-gatherer-heartbeat.json; do
    printf '{}\n' >"$agg/$f"
  done
  printf '{}\n' >"$agg/snapshots/snap1.json"
  printf '{}\n' >"$meta/latest.json"
  printf '{}\n' >"$meta/history.jsonl"
  printf 'dump\n' >"$HOME_DIR/backups/db-dumps/$DATE_ARG/dump.sql"
  echo "$PRESET" >"$HOME_DIR/backups/dashboard/.last-run-epoch"
  if [[ -n "$break_rel" ]]; then
    if [[ "$break_rel" == MISSING:* ]]; then
      rm -f "${HOME_DIR}/${break_rel#MISSING:}"
    else
      chmod 000 "${HOME_DIR}/${break_rel}"
    fi
  fi
  HOME="$HOME_DIR" PATH="$BIN:$PATH" BWS_ACCESS_TOKEN="fake-token" \
    RCLONE_STUB_DIR="$STORE_DIR" \
    PM_DB_DUMP_SCRIPT="$HOME_DIR/no-such-dump-script.sh" \
    bash "$SCRIPT" "$DATE_ARG" >"$TMP_ROOT/$name.log" 2>&1
  RC=$?
}

marker() { cat "$HOME_DIR/backups/dashboard/.last-run-epoch" 2>/dev/null || echo missing; }
uploads() { find "$STORE_DIR" -type f 2>/dev/null | wc -l; }

expect_copy_failure() {
  local name="$1" needle="$2"
  if [[ "$RC" -ne 0 ]]; then
    echo "ok: $name: script exited non-zero ($RC)"
  else
    fail "$name: expected non-zero exit, got 0; log: $(cat "$TMP_ROOT/$name.log")"
  fi
  if grep -q "pm-dashboard-backup: FAILED dataset copy failed: .*${needle}" "$TMP_ROOT/$name.log"; then
    echo "ok: $name: FAILED line names $needle"
  else
    fail "$name: FAILED line does not name $needle; log: $(cat "$TMP_ROOT/$name.log")"
  fi
  if [[ "$(uploads)" -eq 0 ]]; then
    echo "ok: $name: nothing uploaded"
  else
    fail "$name: $(uploads) file(s) uploaded on a failed run"
  fi
  if [[ "$(marker)" == "$PRESET" ]]; then
    echo "ok: $name: marker unchanged at $PRESET"
  else
    fail "$name: marker advanced on a failed run — was $PRESET, now $(marker)"
  fi
}

setup_and_run unreadable-agg ".local/state/pm-aggregator/actions.json"
expect_copy_failure unreadable-agg "actions.json"

setup_and_run unreadable-snapshots ".local/state/pm-aggregator/snapshots/snap1.json"
expect_copy_failure unreadable-snapshots "snapshots"

setup_and_run unreadable-meta "atlas/meta-quota-export/latest.json"
expect_copy_failure unreadable-meta "latest.json"

setup_and_run unreadable-dumps "backups/db-dumps/$DATE_ARG/dump.sql"
expect_copy_failure unreadable-dumps "db-dumps"

# Control: missing dataset files still only WARN; the run succeeds,
# uploads, and advances the marker (absent is not unreadable).
setup_and_run missing-warn "MISSING:.local/state/pm-aggregator/comments.json"
if [[ "$RC" -eq 0 ]]; then
  echo "ok: missing-warn: script exited 0"
else
  fail "missing-warn: expected exit 0, got $RC; log: $(cat "$TMP_ROOT/missing-warn.log")"
fi
if grep -q "WARN missing .*comments.json" "$TMP_ROOT/missing-warn.log"; then
  echo "ok: missing-warn: WARN printed for the missing file"
else
  fail "missing-warn: no WARN for comments.json; log: $(cat "$TMP_ROOT/missing-warn.log")"
fi
if [[ "$(uploads)" -eq 2 ]]; then
  echo "ok: missing-warn: archive uploaded to both stub remotes"
else
  fail "missing-warn: expected 2 uploads, got $(uploads)"
fi
if [[ "$(marker)" =~ ^[0-9]+$ ]] && [[ "$(marker)" -gt "$PRESET" ]]; then
  echo "ok: missing-warn: marker advanced past $PRESET (now $(marker))"
else
  fail "missing-warn: marker did not advance on a successful run — was $PRESET, now $(marker)"
fi

if (( failures > 0 )); then
  echo "pm-dashboard-backup copy tests: $failures failure(s)" >&2
  exit 1
fi
echo "pm-dashboard-backup copy tests: all passed"
